// Analyze Signals (Saham)
// Mode: Run Once for All Items
// Menghitung SMA 50, SMA 200, RSI 14 lalu mendeteksi sinyal untuk setiap item (aset)

// ---- Parameter yang mudah diubah ----
const RSI_PERIOD = 14;
const RSI_OVERSOLD = 30;     // RSI < 30  -> RSI Oversold
const RSI_OVERBOUGHT = 70;   // RSI > 70  -> RSI Overbought
const MA_SHORT = 50;
const MA_LONG = 200;
const CROSS_LOOKBACK = 5;    // persilangan dianggap "baru" bila terjadi dalam 5 candle terakhir

// ---- Fungsi indikator ----
// SMA periode p; offset = mundur berapa candle dari yang terbaru
function sma(closes, p, offset = 0) {
  if (closes.length < p + offset) return null;           // data tidak cukup
  const slice = closes.slice(closes.length - p - offset, closes.length - offset);
  return slice.reduce((a, b) => a + b, 0) / p;
}

// RSI dengan smoothing Wilder
function rsi(closes, p = 14) {
  if (closes.length <= p) return null;
  let gain = 0, loss = 0;
  for (let i = 1; i <= p; i++) {
    const d = closes[i] - closes[i - 1];
    if (d >= 0) gain += d; else loss -= d;
  }
  let avgGain = gain / p, avgLoss = loss / p;
  for (let i = p + 1; i < closes.length; i++) {
    const d = closes[i] - closes[i - 1];
    avgGain = (avgGain * (p - 1) + (d > 0 ? d : 0)) / p;
    avgLoss = (avgLoss * (p - 1) + (d < 0 ? -d : 0)) / p;
  }
  if (avgLoss === 0) return 100;
  return 100 - 100 / (1 + avgGain / avgLoss);
}

const fmt = (v) => (v === null || v === undefined || Number.isNaN(v)) ? 'N/A' : (Math.round(v * 100) / 100).toFixed(2);

// ---- Proses setiap aset ----
const out = [];
for (const item of $input.all()) {
  const result = item.json && item.json.chart && item.json.chart.result && item.json.chart.result[0];
  if (!result) continue;                                   // respons tidak valid, lewati

  const meta = result.meta || {};
  const rawCloses = (result.indicators && result.indicators.quote && result.indicators.quote[0].close) || [];
  const closes = rawCloses.filter((v) => v !== null && v !== undefined);   // buang candle kosong
  if (closes.length === 0) continue;

  const lastClose = closes[closes.length - 1];
  const ma50 = sma(closes, MA_SHORT);
  const ma200 = sma(closes, MA_LONG);
  const rsiVal = rsi(closes, RSI_PERIOD);

  // Deteksi persilangan baru (membandingkan selisih MA50-MA200 sekarang vs beberapa candle lalu)
  let crossBaru = false;
  const ma50Prev = sma(closes, MA_SHORT, CROSS_LOOKBACK);
  const ma200Prev = sma(closes, MA_LONG, CROSS_LOOKBACK);

  const signals = [];
  if (rsiVal !== null && rsiVal < RSI_OVERSOLD) signals.push('🟢 RSI Oversold (RSI < ' + RSI_OVERSOLD + ')');
  if (rsiVal !== null && rsiVal > RSI_OVERBOUGHT) signals.push('🔴 RSI Overbought (RSI > ' + RSI_OVERBOUGHT + ')');

  if (ma50 !== null && ma200 !== null) {
    if (ma50 > ma200) {
      crossBaru = ma50Prev !== null && ma200Prev !== null && ma50Prev <= ma200Prev;
      signals.push('🟡 Golden Cross (MA50 > MA200)' + (crossBaru ? ' - persilangan baru' : ''));
    } else if (ma50 < ma200) {
      crossBaru = ma50Prev !== null && ma200Prev !== null && ma50Prev >= ma200Prev;
      signals.push('⚫ Death Cross (MA50 < MA200)' + (crossBaru ? ' - persilangan baru' : ''));
    }
  }

  out.push({ json: {
    symbol: meta.symbol || item.json.symbol || 'N/A',
    currency: meta.currency || '',
    jumlahData: closes.length,
    lastClose: fmt(lastClose),
    rsi: fmt(rsiVal),
    ma50: fmt(ma50),
    ma200: ma200 === null ? 'N/A (data < ' + MA_LONG + ' candle)' : fmt(ma200),
    hasSignal: signals.length > 0,
    signalText: signals.length > 0 ? signals.join('\n') : '⚪ Tidak ada sinyal saat ini'
  } });
}

return out;

